from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    frequency = parts[0]
    step = int(parts[1])
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                "FR": 4, "SA": 5, "SU": 6}

    if frequency == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())
    elif frequency == "MONTHLY":
        initial_month = first.year * 12 + first.month - 1
        number = int(parts[2])
        target_weekday = weekdays[parts[3]] if len(parts) == 4 else None
    else:
        month, day = map(int, parts[2].split("-"))

    result = []
    period = 0

    while len(result) < count:
        candidates = []

        if frequency == "WEEKLY":
            base = monday + timedelta(weeks=period * step)
            candidates = [base + timedelta(days=wd) for wd in selected]

        elif frequency == "MONTHLY":
            year, month_index = divmod(initial_month + period * step, 12)
            month = month_index + 1
            last_day = monthrange(year, month)[1]

            if target_weekday is None:
                day = last_day if number == -1 else number
            elif number == -1:
                last_weekday = date(year, month, last_day).weekday()
                day = last_day - (last_weekday - target_weekday) % 7
            else:
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (target_weekday - first_weekday) % 7
                day += 7 * (number - 1)

            if day <= last_day:
                candidates = [date(year, month, day)]

        else:
            year = first.year + period * step
            try:
                candidates = [date(year, month, day)]
            except ValueError:
                pass

        for candidate in candidates:
            if candidate >= first:
                result.append(candidate.isoformat())
                if len(result) == count:
                    return result

        period += 1

    return result
